qualified_questions.sparql_query:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <https://git.onem2m.org/MAS/BaseOntology/raw/master/base_ontology.owl#>

SELECT ?dataType
WHERE {
  ?property rdf:type owl:DatatypeProperty ;
           rdfs:domain BO:SimpleTypeVariable ;
           rdfs:range ?dataType .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <https://git.onem2m.org/MAS/BaseOntology/raw/master/base_ontology.owl#>

SELECT (COUNT(DISTINCT ?dataType) AS ?count)
WHERE {
  ?simpleTypeVariable rdf:type BO:SimpleTypeVariable .
  ?property rdf:type owl:DatatypeProperty ;
            rdfs:domain BO:SimpleTypeVariable ;
            rdfs:range ?dataType .
  ?simpleTypeVariable ?property ?value .
  FILTER(?dataType != rdfs:Literal)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/ontology/BO#>

SELECT ?measuringFunctionDifference
WHERE {
  {
    SELECT (GROUP_CONCAT(DISTINCT ?measuringFunctionProperty; separator=", ") AS ?measuringFunctionDifference)
    WHERE {
      BO:MeasuringFunction rdfs:subClassOf* ?superClass .
      ?superClass rdfs:subClassOf [ 
        a owl:Restriction ;
        owl:onProperty ?property ;
        owl:someValuesFrom ?value
      ] .
      FILTER(?superClass != owl:Thing)
    }
  }
  UNION
  {
    SELECT (GROUP_CONCAT(DISTINCT ?otherFunctionProperty; separator=", ") AS ?measuringFunctionDifference)
    WHERE {
      ?otherFunction rdfs:subClassOf* BO:Function ;
                     rdfs:subClassOf [ 
                       a owl:Restriction ;
                       owl:onProperty ?property ;
                       owl:someValuesFrom ?value
                     ] .
      FILTER(?otherFunction != BO:MeasuringFunction && ?otherFunction != owl:Thing)
    }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property
WHERE {
  ?property rdf:type owl:ObjectProperty
}
